"""Actual current477 per-view counts; views are never pooled as distinct territories."""
import argparse,json,hashlib
from pathlib import Path
import pandas as pd
B=Path(__file__).resolve().parent;BASE=B.parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);a=ap.parse_args();out=Path(a.output);assert not out.exists();rows=[];frequencies=[];bindings=[]
 views=[('operational_forest',str(cap),B/f'normalized_source477_v1/cap{cap:03}_supported_end_forest',B/f'classified_source477_v1/cap{cap:03}_supported_end_forest') for cap in (30,45,60,90,120)]+[('empirical_level',str(i),B/f'normalized_empirical_source477_v1/level_{i:03}',B/f'classified_empirical_source477_v1/level_{i:03}') for i in range(4)]
 for kind,label,n,t in views:
  nr=json.loads((n/'receipt.json').read_text());tr=json.loads((t/'receipt.json').read_text());tp=t/'complete_typology.parquet';assert nr['normalized_units_sha256']==tr['input_units_sha256'] and sha(tp)==tr['files']['complete_typology.parquet'];types=pd.read_parquet(tp);assert types.unit_id.is_unique and len(types)==nr['n_units'] and types.primary_type_id.notna().all();name=f'{kind}_{label}';rows.append({'view_id':name,'view_kind':kind,'candidate_cap_minutes':int(label) if kind=='operational_forest' else None,'empirical_level':int(label) if kind=='empirical_level' else None,'n_units':len(types),'n_territorial_units':int(types.unit_role.eq('territorial_unit').sum()),'n_protected_carry':int(types.unit_role.eq('protected_carry').sum()),'n_primary_measured_types':types.primary_type_id.nunique(),'all_units_typed':True,'source_axis_members_per_view':173858,'ordinary_population_axis_members_per_view':173856,'external_context_anchor_members_per_view':2,'source353_recoveries_in_effective_axis':nr['n_primary2010_overrides']})
  for (role,code,nm),g in types.groupby(['unit_role','primary_type_id','primary_type_name'],dropna=False):frequencies.append({'view_id':name,'unit_role':role,'primary_type_id':code,'primary_type_name':nm,'n_units':len(g)})
  bindings.append({'view_id':name,'normalized_path':str(n),'normalization_receipt_sha256':sha(n/'receipt.json'),'normalized_units_sha256':nr['normalized_units_sha256'],'classification_path':str(t),'classification_receipt_sha256':sha(t/'receipt.json'),'types_sha256':sha(tp),'normalizer_sha256':nr['code_sha256'],'classifier_sha256':tr['classifier_sha256']})
 out.mkdir();pd.DataFrame(rows).to_csv(out/'actual_view_counts.csv',index=False);pd.DataFrame(frequencies).to_csv(out/'all_type_codes_counts_by_view_and_role.csv',index=False);(out/'source_binding.json').write_text(json.dumps(bindings,ensure_ascii=False,indent=2));table='| Разбиение | Территориальные единицы | Сохранённые отдельные записи | Измеренные типы |\n|---|---:|---:|---:|\n'+'\n'.join('| '+str(r['view_id'])+' | '+str(r['n_territorial_units'])+' | '+str(r['n_protected_carry'])+' | '+str(r['n_primary_measured_types'])+' |' for r in rows);text='Фактическая полная типизация текущей семьи477\n\n'+table+'\n\nКаждая строка — отдельное разбиение одной исходной оси, а не независимая выборка. Эмпирические уровни0–3 — четыре фактически отличающихся вложенных устойчивых среза; транспортные пределы30–120мин в отдельном семействе являются операционными сценариями. Protected carry сохраняет измеренный собственный профиль; неизвестная динамика не заменена стабильностью. Типы описывают измеренную структуру и траекторию, не доказывают причинный механизм Word.\n';(out/'READOUT.md').write_text(text);receipt={'status':'COMPUTED_ACTUAL9VIEW_COUNTS_PENDING_FINAL_PACKAGE_REVIEW','n_views':len(rows),'all_units_typed_in_every_view':True,'views_must_not_be_pooled':True,'scientific_final_allowed':False,'files':{p.name:sha(p) for p in out.iterdir() if p.is_file()},'code_sha256':sha(__file__)};(out/'receipt.json').write_text(json.dumps(receipt,indent=2));print(table)
if __name__=='__main__':main()
